/* Interpret existing frozen results; no training or changes to scores. */
(()=>{const el=id=>document.getElementById(id);const watch=(id,fn)=>{const target=el(id);if(!target)return;new MutationObserver(fn).observe(target,{childList:true,subtree:true,characterData:true});fn()};
if(el('manager-model')){
 watch('model-verdict',()=>{if(typeof model==='undefined'||!model)return;const d=model.test.models[model.chosen],u=model.test.models.uf,t=d.top20.Arrematada,rt=u.top20.Arrematada;const hits=Math.round(t.n*t.precision),ref=Math.round(rt.n*rt.precision);el('manager-model').textContent=`Para uma equipe que examinasse ${N(t.n)} das ${N(d.n)} áreas históricas, a fila do modelo reuniria ${N(hits)} arrematações, contra ${N(ref)} pela referência por estado: ${N(hits-ref)} casos a mais. Isso sugere um piloto de triagem; não comprova economia de trabalho nem desempenho futuro. O modelo acertou apenas 16 das 686 conquistas como classe, portanto não serve para decidir sozinho o destino de cada área.`});
 watch('model-summary',()=>{if(typeof model==='undefined'||!model)return;const t=model.test.models[model.chosen].top20.Arrematada;el('model-highlight').textContent='Exemplo: revisar 20% das áreas da 8ª rodada';el('model-f1').textContent=N(Math.round(t.n*t.precision))+' de '+N(t.n)});
 // Explain the primary card once, outside its observer, to avoid feedback loops.
 watch('kpis',()=>{if(typeof model==='undefined'||!model)return;const d=model.test.models[model.chosen],t=d.top20.Arrematada,u=model.test.models.uf.top20.Arrematada;const text=`Áreas arrematadas encontradas na seleção histórica (${P(t.precision)}), frente a ${N(Math.round(u.n*u.precision))} da referência por estado. O uso proposto é direcionar revisão técnica; ainda não selecionar automaticamente a próxima rodada. Este teste se refere à 8ª rodada completa, independentemente dos filtros acima.`;if(el('model-summary').textContent!==text)el('model-summary').textContent=text});
 watch('sim-kpis',()=>{if(typeof predictions==='undefined'||!predictions)return;const stats=el('sim-kpis').querySelectorAll('strong');if(stats.length<4)return;el('sim-decision').textContent=`Leitura da seleção: com capacidade para ${stats[0].textContent} áreas deste recorte, a fila contém ${stats[1].textContent} casos do resultado escolhido. A proporção é ${stats[2].textContent}; a referência por estado alcança ${stats[3].textContent} com a mesma capacidade. Compare as duas antes de propor um piloto. A seleção não mede aptidão jurídica nem substitui a revisão das áreas.`});
}
if(el('manager-v4')){
 watch('ranks',()=>{if(typeof report==='undefined'||!report)return;const d=report.ranking.lance_positivo,t=d.test,u=d.test_references.frequencia_uf;el('manager-v4').textContent=`Exemplo deste experimento V4: ao examinar ${num(t.reviewed)} áreas, o modelo reuniu ${num(t.captured)} com lance positivo (${pct(t.precision20)}). A referência por estado reuniu ${num(u.captured)} (${pct(u.precision20)}). Para o gestor, o resultado não justifica preferir o modelo complexo nesta tarefa. A seleção pode ser estudada como fila de revisão, não como decisão de oferta.`});
 watch('profile-info',()=>{if(typeof report==='undefined'||!report)return;const p=report.clustering.profiles.find(x=>String(x.cluster)===el('profile').value);if(!p)return;el('profile-decision').textContent=`Este perfil reúne processos com idade mediana de ${num(p.train_medians.idade_processo_no_corte)} anos e ${num(p.train_medians.dias_observados)} dias distintos com eventos no treino. O gestor pode comparar uma amostra desses processos e preparar revisões com questões comuns. O perfil não identifica, por si só, um gargalo ou uma causa de desinteresse; a equipe precisa interpretar os registros.`});
 watch('sim-metrics',()=>{const a=el('sim-metrics').querySelectorAll('strong');if(a.length<4)return;el('v4-sim-decision').textContent=`Se a equipe revisasse ${a[0].textContent} áreas dessa rodada histórica, encontraria ${a[1].textContent} casos do objetivo escolhido. Isso representa ${a[2].textContent} da seleção e ${a[3].textContent} de todos os casos de interesse. Os casos fora da fila continuam importantes: reduzir a revisão não autoriza descartá-los.`});
}
})();
